\set ON_ERROR_STOP on
BEGIN TRANSACTION READ ONLY;
DO $count_review$
DECLARE invalid_count bigint;
BEGIN
 IF to_regclass('public.inventory_operations') IS NOT NULL THEN
  EXECUTE $sql$ SELECT count(*) FROM inventory_operations WHERE NOT ((((operation_type = 'TRANSFER' AND submitted_at IS NULL AND submitted_by IS NULL AND approved_at IS NULL AND approved_by IS NULL AND rejected_at IS NULL AND rejected_by IS NULL AND reject_reason IS NULL) OR (operation_type IN ('MANUAL_ADJUSTMENT', 'CYCLE_COUNT') AND ((status = 'DRAFT' AND submitted_at IS NULL AND submitted_by IS NULL AND approved_at IS NULL AND approved_by IS NULL AND rejected_at IS NULL AND rejected_by IS NULL AND reject_reason IS NULL) OR (status = 'SUBMITTED' AND submitted_at IS NOT NULL AND submitted_by IS NOT NULL AND approved_at IS NULL AND approved_by IS NULL AND rejected_at IS NULL AND rejected_by IS NULL AND reject_reason IS NULL) OR (status IN ('APPROVED', 'POSTED') AND submitted_at IS NOT NULL AND submitted_by IS NOT NULL AND approved_at IS NOT NULL AND approved_by IS NOT NULL AND approved_by <> created_by AND rejected_at IS NULL AND rejected_by IS NULL AND reject_reason IS NULL) OR (status = 'REJECTED' AND submitted_at IS NOT NULL AND submitted_by IS NOT NULL AND approved_at IS NULL AND approved_by IS NULL AND rejected_at IS NOT NULL AND rejected_by IS NOT NULL AND rejected_by <> created_by AND reject_reason IS NOT NULL AND length(trim(reject_reason)) > 0) OR (status = 'CANCELLED' AND ((submitted_at IS NULL AND submitted_by IS NULL AND approved_at IS NULL AND approved_by IS NULL AND rejected_at IS NULL AND rejected_by IS NULL AND reject_reason IS NULL) OR (submitted_at IS NOT NULL AND submitted_by IS NOT NULL AND approved_at IS NULL AND approved_by IS NULL AND rejected_at IS NULL AND rejected_by IS NULL AND reject_reason IS NULL) OR (submitted_at IS NOT NULL AND submitted_by IS NOT NULL AND approved_at IS NOT NULL AND approved_by IS NOT NULL AND approved_by <> created_by AND rejected_at IS NULL AND rejected_by IS NULL AND reject_reason IS NULL)))))) OR (operation_type = 'CYCLE_COUNT' AND status IN ('POSTED', 'CANCELLED') AND submitted_at IS NULL AND submitted_by IS NULL AND approved_at IS NULL AND approved_by IS NULL AND rejected_at IS NULL AND rejected_by IS NULL AND reject_reason IS NULL))) $sql$ INTO invalid_count;
  IF invalid_count > 0 THEN RAISE EXCEPTION 'inventory count review preflight: % incompatible operations', invalid_count; END IF;
 END IF;
END $count_review$;
COMMIT;
